function describe(n, d) {
  if (!n) return d + ": MISSING";
  const o = { id: n.id, name: n.name, type: n.type, w: n.width, h: n.height };
  if ("fills" in n && Array.isArray(n.fills)) o.fills = n.fills;
  if ("strokes" in n && Array.isArray(n.strokes)) o.strokes = n.strokes;
  if ("strokeWeight" in n) o.strokeWeight = n.strokeWeight;
  if ("cornerRadius" in n && typeof n.cornerRadius === "number") o.radius = n.cornerRadius;
  if (n.type === "TEXT") {
    o.fontName = n.fontName;
    o.fontSize = n.fontSize;
    o.characters = n.characters.slice(0, 80);
    if (n.textAlignHorizontal) o.align = n.textAlignHorizontal;
  }
  if ("children" in n && d < 3) o.children = n.children.map(c => describe(c, d + 1));
  return o;
}
const out = {};
out.button = describe(await figma.getNodeByIdAsync("1:28"), 0);
out.statusBar = describe(await figma.getNodeByIdAsync("1:33"), 0);
out.homeIndicator = describe(await figma.getNodeByIdAsync("1:44"), 0);
out.portraitAidan = describe(await figma.getNodeByIdAsync("5:112"), 0);
out.iconBack = describe(await figma.getNodeByIdAsync("5:26"), 0);
out.logoMeet = describe(await figma.getNodeByIdAsync("5:4"), 0);
return JSON.stringify(out, null, 1);

