const TR={type:'ON_PRESS'};
function mk(dest){
  const t={type:'DISSOLVE',duration:0.25,easing:{type:'EASE_IN_AND_OUT'}};
  return [
    {trigger:TR,action:{type:'NAVIGATE',destinationId:dest,transition:t}},
    {trigger:TR,action:{type:'NODE',destinationId:dest,navigation:'NAVIGATE',transition:t}},
    {trigger:TR,action:{type:'NAVIGATE',destinationId:dest,transition:null}}
  ];
}
async function link(id,dest){const nd=await n(id);let used=null;for(const r of mk(dest)){try{nd.reactions=[r];used=r.action.type;break}catch(e){}}if(!used)throw new Error('link failed '+id+' -> '+dest);return used}
function hot(f,x,y,w,h,dest){const r=figma.createRectangle();r.resize(w,h);r.x=x;r.y=y;r.fills=[];r.name='Hotspot';f.appendChild(r);return link(r.id,dest)}

