const t1={type:'DISSOLVE',duration:0.25,easing:{type:'EASE_IN_AND_OUT'}};
const t2={type:'INSTANT'};
const t3=null;
const t4={type:'SMART_ANIMATE',duration:0.25,easing:{type:'EASE_IN_AND_OUT'}};
const actions=[];
for(const at of ['NAVIGATE','NODE','CHANGE_TO','OVERLAY','SWAP']){for(const [tn,tv] of [['dissolve',t1],['instant',t2],['null',t3],['smart',t4]]){
  actions.push({at,tn,a:{type:at,destinationId:'9:59',navigation:'NAVIGATE',transition:tv}});
  actions.push({at,tn,a:{type:at,destinationId:'9:59',transition:tv}});
}}
for(const at of ['BACK','CLOSE']){actions.push({at,tn:'x',a:{type:at}})}
const triggers=[{type:'ON_PRESS'},{type:'ON_CLICK'}];
const results=[];
for(const trig of triggers){for(const it of actions){
  try{r.reactions=[{trigger:trig,action:it.a}];results.push('OK:'+trig.type+'|'+it.at+'|'+it.tn+'|'+(it.a.navigation||'nonav'));}catch(e){const m=String(e.message||e).slice(0,220);results.push('ERR:'+trig.type+'|'+it.at+'|'+it.tn+'|'+(it.a.navigation||'nonav')+' :: '+m.replace(/\n/g,' '));}
}}
r.remove();
return results.join('\n');

